import numpy as np, time
def timeit(f,size,reps=2000):
  ts=[]
  for _ in range(reps):
    A=np.random.normal(size=(size,size))
    t0=time.perf_counter(); f(A); ts.append(time.perf_counter()-t0)
  return np.median(ts)*1e6

def f_eig(A): np.linalg.eig(A)
def f_vals(A): np.linalg.eigvals(A)
def f_solve(A):
  n=A.shape[0]; np.linalg.solve(A+np.eye(n), np.ones(n))

for size in [2,4,6,8,10]:
  print(size, 'eig',round(timeit(f_eig,size),2),'vals',round(timeit(f_vals,size),2),'solve',round(timeit(f_solve,size),2))
"
